-- =========================================================
-- Une Caixas (Fechamento Certo) - Schema PostgreSQL
-- Baseado no documento "Lógica do Banco de Dados"
-- =========================================================

-- =========================================================
-- 1. POSTOS (local físico)
-- =========================================================
CREATE TABLE IF NOT EXISTS "postos" (
    "posto_id"    INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "nome"        VARCHAR(255) NOT NULL,
    "endereco"    VARCHAR(255), -- endereço completo, montado a partir dos campos abaixo
    "telefone"    VARCHAR(20),
    "cep"         VARCHAR(9),
    "logradouro"  VARCHAR(255),
    "numero"      VARCHAR(20),
    "bairro"      VARCHAR(120),
    "cidade"      VARCHAR(120),
    "uf"          VARCHAR(2),
    "complemento" VARCHAR(120),
    "plano"       VARCHAR(20) NOT NULL DEFAULT 'basico',
    "ativo"       BOOLEAN NOT NULL DEFAULT true, -- inativar mantém o histórico
    "created_at"  TIMESTAMP NOT NULL DEFAULT now(),
    PRIMARY KEY ("posto_id")
);

-- =========================================================
-- 2. USUARIOS (gerentes e administradores do sistema, únicos que logam)
-- =========================================================
CREATE TABLE IF NOT EXISTS "usuarios" (
    "usuario_id"  INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "nome"        VARCHAR(255) NOT NULL,
    "email"       VARCHAR(255) NOT NULL UNIQUE,
    "senha"       VARCHAR(255) NOT NULL, -- hash, nunca texto puro
    "created_at"  TIMESTAMP NOT NULL DEFAULT now(),
    "ativo" BOOLEAN NOT NULL DEFAULT true,
    "perfil"        VARCHAR(10) NOT NULL DEFAULT 'gerente',
    "telefone"      VARCHAR(20),
    "ultimo_acesso" TIMESTAMP, -- nulo enquanto o gerente nunca entrou (status pendente)
    PRIMARY KEY ("usuario_id")
);

-- =========================================================
-- 3. POSTOS_USUARIOS (tabela associativa N:N postos <-> usuarios)
-- =========================================================
CREATE TABLE IF NOT EXISTS "postos_usuarios" (
    "posto_id"    INTEGER NOT NULL,
    "usuario_id"  INTEGER NOT NULL,
    "created_at"  TIMESTAMP NOT NULL DEFAULT now(), -- data do vínculo
    PRIMARY KEY ("posto_id", "usuario_id"),
    FOREIGN KEY ("posto_id")   REFERENCES "postos"("posto_id")     ON UPDATE CASCADE ON DELETE CASCADE,
    FOREIGN KEY ("usuario_id") REFERENCES "usuarios"("usuario_id") ON UPDATE CASCADE ON DELETE CASCADE
);

-- =========================================================
-- 4. EMPRESAS (CNPJ que opera dentro de um posto)
-- =========================================================
CREATE TABLE IF NOT EXISTS "empresas" (
    "empresa_id"  INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "posto_id"    INTEGER NOT NULL,
    "nome"        VARCHAR(255) NOT NULL,
    "cnpj"        VARCHAR(18) NOT NULL UNIQUE,
    "tipo"        VARCHAR(20) NOT NULL CHECK ("tipo" IN ('combustivel', 'conveniencia')),
    "inscricao_estadual" VARCHAR(20),
    "created_at"  TIMESTAMP NOT NULL DEFAULT now(),
    PRIMARY KEY ("empresa_id"),
    FOREIGN KEY ("posto_id") REFERENCES "postos"("posto_id") ON UPDATE CASCADE ON DELETE RESTRICT
);

-- =========================================================
-- 5. MAQUINAS (pertencem a uma empresa, nunca direto ao posto)
-- =========================================================
CREATE TABLE IF NOT EXISTS "maquinas" (
    "maquina_id"  INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "empresa_id"  INTEGER NOT NULL,
    "nome"        VARCHAR(255) NOT NULL,
    "ativo"       BOOLEAN NOT NULL DEFAULT true,
    "created_at"  TIMESTAMP NOT NULL DEFAULT now(),
    PRIMARY KEY ("maquina_id"),
    FOREIGN KEY ("empresa_id") REFERENCES "empresas"("empresa_id") ON UPDATE CASCADE ON DELETE RESTRICT
);

-- =========================================================
-- 6. OPERADORES (frentistas/funcionários, não logam)
-- =========================================================
CREATE TABLE IF NOT EXISTS "operadores" (
    "operador_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "empresa_id"  INTEGER NOT NULL,
    "nome"        VARCHAR(255) NOT NULL,
    "ativo"       BOOLEAN NOT NULL DEFAULT true,
    "created_at"  TIMESTAMP NOT NULL DEFAULT now(),
    PRIMARY KEY ("operador_id"),
    FOREIGN KEY ("empresa_id") REFERENCES "empresas"("empresa_id") ON UPDATE CASCADE ON DELETE RESTRICT
);

-- =========================================================
-- 7. FECHAMENTOS (documento central, um por posto/data)
-- =========================================================
CREATE TABLE IF NOT EXISTS "fechamentos" (
    "fechamento_id"              INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "posto_id"                   INTEGER NOT NULL,
    "usuario_id"                 INTEGER NOT NULL, -- gerente que fez o fechamento
    "data_referencia"            DATE NOT NULL,
    "valor_dinheiro_declarado"   DECIMAL(12,2),
    "valor_dinheiro_esperado"    DECIMAL(12,2),
    "status"                     VARCHAR(20) NOT NULL DEFAULT 'em_analise'
                                  CONSTRAINT "fechamentos_status_check"
                                  CHECK ("status" IN ('ok', 'com_divergencia', 'em_analise', 'arquivado')),
    "created_at"                 TIMESTAMP NOT NULL DEFAULT now(),
    "updated_at"                 TIMESTAMP NOT NULL DEFAULT now(),
    PRIMARY KEY ("fechamento_id"),
    FOREIGN KEY ("posto_id")   REFERENCES "postos"("posto_id")     ON UPDATE CASCADE ON DELETE RESTRICT,
    FOREIGN KEY ("usuario_id") REFERENCES "usuarios"("usuario_id") ON UPDATE CASCADE ON DELETE RESTRICT,
    UNIQUE ("posto_id", "data_referencia") -- um fechamento por posto por dia
);

-- =========================================================
-- 8. FECHAMENTO_MAQUINAS (conferência linha a linha por máquina)
-- =========================================================
CREATE TABLE IF NOT EXISTS "fechamento_maquinas" (
    "fechamento_maquina_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "fechamento_id"         INTEGER NOT NULL,
    "maquina_id"            INTEGER NOT NULL,
    "operador_id"           INTEGER, -- nullable: quem operou naquele turno
    "turno"                 VARCHAR(20),
    "valor_esperado"        DECIMAL(12,2),
    "valor_recebido"        DECIMAL(12,2),
    "diferenca"             DECIMAL(12,2) GENERATED ALWAYS AS ("valor_recebido" - "valor_esperado") STORED,
    PRIMARY KEY ("fechamento_maquina_id"),
    FOREIGN KEY ("fechamento_id") REFERENCES "fechamentos"("fechamento_id") ON UPDATE CASCADE ON DELETE CASCADE,
    FOREIGN KEY ("maquina_id")    REFERENCES "maquinas"("maquina_id")       ON UPDATE CASCADE ON DELETE RESTRICT,
    FOREIGN KEY ("operador_id")   REFERENCES "operadores"("operador_id")    ON UPDATE CASCADE ON DELETE SET NULL
);

-- =========================================================
-- 9. FECHAMENTO_EMPRESA (opcional: snapshot calculado por empresa)
-- Não obrigatória — pode ser calculada via query somando
-- fechamento_maquinas agrupado por empresa_id da máquina.
-- Deixada aqui pronta caso você queira guardar o snapshot.
-- =========================================================
CREATE TABLE IF NOT EXISTS "fechamento_empresa" (
    "fechamento_empresa_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "fechamento_id"         INTEGER NOT NULL,
    "empresa_id"            INTEGER NOT NULL,
    "valor_esperado"        DECIMAL(12,2),
    "valor_recebido"        DECIMAL(12,2),
    "diferenca"             DECIMAL(12,2) GENERATED ALWAYS AS ("valor_recebido" - "valor_esperado") STORED,
    PRIMARY KEY ("fechamento_empresa_id"),
    FOREIGN KEY ("fechamento_id") REFERENCES "fechamentos"("fechamento_id") ON UPDATE CASCADE ON DELETE CASCADE,
    FOREIGN KEY ("empresa_id")    REFERENCES "empresas"("empresa_id")       ON UPDATE CASCADE ON DELETE RESTRICT,
    UNIQUE ("fechamento_id", "empresa_id")
);

-- =========================================================
-- 10. DIVERGENCIAS
-- =========================================================
CREATE TABLE IF NOT EXISTS "divergencias" (
    "divergencia_id"        INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "fechamento_id"         INTEGER NOT NULL,
    "fechamento_maquina_id" INTEGER, -- nullable: se a divergência for geral, não de uma máquina específica
    "operador_id"           INTEGER, -- nullable: vinculado pelo gerente durante a investigação
    "valor_diferenca"       DECIMAL(12,2),
    "status"                VARCHAR(20) NOT NULL DEFAULT 'pendente'
                             CHECK ("status" IN ('pendente', 'investigada', 'resolvida')),
    "created_at"            TIMESTAMP NOT NULL DEFAULT now(),
    PRIMARY KEY ("divergencia_id"),
    FOREIGN KEY ("fechamento_id")         REFERENCES "fechamentos"("fechamento_id")                 ON UPDATE CASCADE ON DELETE CASCADE,
    FOREIGN KEY ("fechamento_maquina_id") REFERENCES "fechamento_maquinas"("fechamento_maquina_id")  ON UPDATE CASCADE ON DELETE SET NULL,
    FOREIGN KEY ("operador_id")           REFERENCES "operadores"("operador_id")                     ON UPDATE CASCADE ON DELETE SET NULL
);

-- =========================================================
-- 11. OBSERVACOES
-- =========================================================
CREATE TABLE IF NOT EXISTS "observacoes" (
    "observacao_id"   INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "fechamento_id"   INTEGER NOT NULL,
    "divergencia_id"  INTEGER, -- nullable
    "usuario_id"      INTEGER NOT NULL,
    "texto"           TEXT NOT NULL,
    "created_at"      TIMESTAMP NOT NULL DEFAULT now(),
    PRIMARY KEY ("observacao_id"),
    FOREIGN KEY ("fechamento_id")  REFERENCES "fechamentos"("fechamento_id")   ON UPDATE CASCADE ON DELETE CASCADE,
    FOREIGN KEY ("divergencia_id") REFERENCES "divergencias"("divergencia_id") ON UPDATE CASCADE ON DELETE SET NULL,
    FOREIGN KEY ("usuario_id")     REFERENCES "usuarios"("usuario_id")         ON UPDATE CASCADE ON DELETE RESTRICT
);

-- =========================================================
-- 12. LOGS_AUDITORIA (fechamentos nunca são apagados, só editados com log)
-- =========================================================
CREATE TABLE IF NOT EXISTS "logs_auditoria" (
    "log_id"           INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "fechamento_id"    INTEGER NOT NULL,
    "usuario_id"       INTEGER NOT NULL,
    "acao"             VARCHAR(255) NOT NULL,
    "campo_alterado"   VARCHAR(255),
    "valor_anterior"   VARCHAR(255),
    "valor_novo"       VARCHAR(255),
    "created_at"       TIMESTAMP NOT NULL DEFAULT now(),
    PRIMARY KEY ("log_id"),
    FOREIGN KEY ("fechamento_id") REFERENCES "fechamentos"("fechamento_id") ON UPDATE CASCADE ON DELETE CASCADE,
    FOREIGN KEY ("usuario_id")    REFERENCES "usuarios"("usuario_id")       ON UPDATE CASCADE ON DELETE RESTRICT
);

-- =========================================================
-- 13. POSTOS_MODULOS (módulos contratados por cliente; o catálogo fica em src/config/catalogo.js)
-- =========================================================
CREATE TABLE IF NOT EXISTS "postos_modulos" (
    "posto_id"    INTEGER NOT NULL,
    "modulo"      VARCHAR(40) NOT NULL,
    "ativo"       BOOLEAN NOT NULL DEFAULT true,
    "updated_at"  TIMESTAMP NOT NULL DEFAULT now(),
    PRIMARY KEY ("posto_id", "modulo"),
    FOREIGN KEY ("posto_id") REFERENCES "postos"("posto_id") ON UPDATE CASCADE ON DELETE CASCADE
);

-- =========================================================
-- 14. LOGS_ATIVIDADE (ações de cadastro e de administração; fechamentos ficam em logs_auditoria)
-- =========================================================
CREATE TABLE IF NOT EXISTS "logs_atividade" (
    "atividade_id" INTEGER GENERATED BY DEFAULT AS IDENTITY,
    "usuario_id"   INTEGER NOT NULL,
    "posto_id"     INTEGER,
    "descricao"    VARCHAR(255) NOT NULL,
    "created_at"   TIMESTAMP NOT NULL DEFAULT now(),
    PRIMARY KEY ("atividade_id"),
    FOREIGN KEY ("usuario_id") REFERENCES "usuarios"("usuario_id") ON UPDATE CASCADE ON DELETE CASCADE,
    FOREIGN KEY ("posto_id")   REFERENCES "postos"("posto_id")     ON UPDATE CASCADE ON DELETE SET NULL
);

-- =========================================================
-- MIGRAÇÃO para bancos criados antes destas alterações.
-- O CREATE TABLE IF NOT EXISTS não altera tabelas que já existem,
-- então estes comandos aplicam as mudanças nelas. Podem rodar várias vezes.
-- =========================================================
ALTER TABLE "postos" ADD COLUMN IF NOT EXISTS "ativo" BOOLEAN NOT NULL DEFAULT true;

ALTER TABLE "postos" ADD COLUMN IF NOT EXISTS "telefone" VARCHAR(20);
ALTER TABLE "postos" ADD COLUMN IF NOT EXISTS "cep" VARCHAR(9);
ALTER TABLE "postos" ADD COLUMN IF NOT EXISTS "logradouro" VARCHAR(255);
ALTER TABLE "postos" ADD COLUMN IF NOT EXISTS "numero" VARCHAR(20);
ALTER TABLE "postos" ADD COLUMN IF NOT EXISTS "bairro" VARCHAR(120);
ALTER TABLE "postos" ADD COLUMN IF NOT EXISTS "cidade" VARCHAR(120);
ALTER TABLE "postos" ADD COLUMN IF NOT EXISTS "uf" VARCHAR(2);
ALTER TABLE "postos" ADD COLUMN IF NOT EXISTS "complemento" VARCHAR(120);
ALTER TABLE "postos" ADD COLUMN IF NOT EXISTS "plano" VARCHAR(20) NOT NULL DEFAULT 'basico';
ALTER TABLE "usuarios" ADD COLUMN IF NOT EXISTS "perfil" VARCHAR(10) NOT NULL DEFAULT 'gerente';
ALTER TABLE "usuarios" ADD COLUMN IF NOT EXISTS "telefone" VARCHAR(20);
ALTER TABLE "usuarios" ADD COLUMN IF NOT EXISTS "ultimo_acesso" TIMESTAMP;
ALTER TABLE "postos_usuarios" ADD COLUMN IF NOT EXISTS "created_at" TIMESTAMP NOT NULL DEFAULT now();
ALTER TABLE "empresas" ADD COLUMN IF NOT EXISTS "inscricao_estadual" VARCHAR(20);

-- Perfis de acesso: o administrador gerencia clientes; o gerente faz os fechamentos.
ALTER TABLE "usuarios" DROP CONSTRAINT IF EXISTS "usuarios_perfil_check";
ALTER TABLE "usuarios" ADD CONSTRAINT "usuarios_perfil_check" CHECK ("perfil" IN ('admin', 'gerente'));

-- Fechamentos podem ser arquivados (nunca apagados).
ALTER TABLE "fechamentos" DROP CONSTRAINT IF EXISTS "fechamentos_status_check";
ALTER TABLE "fechamentos" ADD CONSTRAINT "fechamentos_status_check"
    CHECK ("status" IN ('ok', 'com_divergencia', 'em_analise', 'arquivado'));

SELECT table_name
FROM information_schema.tables
WHERE table_schema = 'public'
ORDER BY table_name;
